/* Captions as a script so they also work when the page is opened straight from a folder. The .vtt files in captions/ hold the same text. */
window.CAPTIONS = {"Lesson1_Theory": [[0.3, 2.146, "Welcome to Headstart algebra."], [2.166, 3.24, "This is Lesson 1:"], [3.26, 5.75, "adding and subtracting algebraic terms."], [5.77, 9.869, "By the end of this video, you'll be able to identify like terms,"], [9.889, 12.7, "and simplify expressions by collecting them."], [14.533, 16.526, "First, some words to know."], [16.546, 18.151, "Here's an expression:"], [18.171, 20.705, "seven x, minus four y, plus nine."], [20.725, 23.956, "Let's use it to meet five important words."], [25.2, 28.137, "A pronumeral is a letter that stands for a number."], [28.157, 30.976, "In this expression, the pronumerals are x and y."], [32.2, 34.615, "A term is one part of an expression."], [34.635, 37.592, "Terms are separated by plus and minus signs,"], [37.612, 40.433, "and the sign in front belongs to the term."], [40.453, 42.801, "So this expression has three terms:"], [42.821, 45.304, "seven x, minus four y, and plus nine."], [46.533, 50.383, "The coefficient is the number multiplying the pronumeral."], [50.403, 52.895, "In seven x, the coefficient is seven."], [52.915, 55.136, "In minus four y, it's minus four."], [55.156, 58.938, "And x on its own means one x, so its coefficient is one."], [60.167, 63.526, "A constant is a term with no pronumeral, just a number."], [63.546, 65.186, "Here, the constant is nine."], [66.433, 70.743, "And an expression is terms joined by plus and minus signs, like this whole thing."], [72.367, 75.331, "The laws of arithmetic still work in algebra."], [75.351, 80.305, "The commutative law says that order doesn't matter when we add or multiply."], [80.325, 84.283, "So a plus b equals b plus a, and a times b equals b times a."], [84.303, 86.936, "This means xy and yx are the same thing."], [86.956, 87.931, "But be careful:"], [87.951, 90.186, "order does matter for subtraction."], [90.206, 93.435, "Five minus two is not the same as two minus five."], [94.667, 99.661, "The associative law says that grouping doesn't matter for adding or multiplying either."], [99.681, 103.579, "We can add a and b first, or b and c first, and get the same answer."], [105.2, 106.188, "Now, like terms."], [106.208, 110.915, "Like terms have exactly the same pronumerals, with exactly the same powers."], [110.935, 113.373, "Only the coefficients can be different."], [114.6, 116.852, "Five x and eight x are like terms."], [116.872, 118.322, "They both have just x."], [119.567, 123.627, "Five x and five y are not like terms, because the letters are different."], [124.867, 126.907, "The order of the letters can change."], [126.927, 128.337, "xy and yx are like terms."], [129.567, 132.805, "To check powers, write them in expanded form."], [132.825, 137.945, "a squared b is a times a times b, but a b squared is a times b times b."], [137.965, 139.9, "So they are not like terms."], [141.533, 145.784, "Now let's simplify an expression by collecting like terms."], [145.804, 147.404, "There are three steps."], [147.424, 149.098, "We'll use this example:"], [149.118, 152.191, "four x, plus three y, plus two x, minus y."], [153.433, 154.054, "Step one:"], [154.074, 156.544, "circle or underline the like terms."], [156.564, 158.892, "The x terms are four x and two x."], [158.912, 161.454, "The y terms are three y and minus y."], [162.7, 163.254, "Step two:"], [163.274, 164.529, "group them together."], [164.549, 166.761, "Each sign goes along with its term."], [168.0, 168.759, "Step three:"], [168.779, 171.166, "add and subtract the coefficients."], [171.186, 174.635, "Four plus two is six, and three minus one is two."], [174.655, 177.042, "So the answer is six x plus two y."], [178.667, 180.621, "Here are two helpful hints."], [180.641, 184.717, "First, the sign in front of a term belongs to that term."], [184.737, 187.935, "If you move the term, take its sign with it."], [187.955, 192.031, "For example, x plus seven y, minus three x, plus five y,"], [192.051, 196.565, "can be regrouped as x minus three x, plus seven y plus five y."], [197.8, 199.82, "Second, x on its own means one x."], [199.84, 201.983, "And unlike terms can't be combined."], [202.003, 205.074, "Three x plus five is already as simple as it gets,"], [205.094, 207.794, "because an x term and a constant are unlike."], [209.433, 212.8, "You should now be able to name the parts of an expression,"], [212.82, 215.136, "decide whether two terms are like terms,"], [215.156, 218.465, "collect like terms while keeping each sign with its term,"], [218.485, 221.152, "and check your answer by substituting a value."], [221.172, 225.707, "Next, watch the worked examples video, then try the questions in your booklet."]], "Lesson1_Worked_Examples": [[0.3, 4.092, "In this video we'll work through six worked examples from Lesson 1."], [4.112, 7.79, "For each one, pause the video and try the problem yourself first."], [7.81, 11.261, "Then follow the think and write steps to check your thinking."], [13.1, 14.321, "Example one:"], [14.341, 16.389, "identify like terms."], [16.409, 18.56, "Group the like terms:"], [18.58, 23.834, "five x, three y, minus two x, four, y, and seven x."], [26.367, 31.011, "Look at the pronumerals in each term, and ignore the coefficients."], [31.031, 34.404, "Five x, minus two x and seven x all have just x."], [35.633, 36.463, "Next group:"], [36.483, 38.859, "three y and y both have just y."], [40.1, 41.262, "Anything left over?"], [41.282, 43.688, "Four is a constant, so it's on its own."], [45.433, 46.485, "Example two:"], [46.505, 48.272, "are they like terms?"], [48.292, 48.897, "Part a:"], [48.917, 49.79, "xy and yx."], [49.81, 50.416, "Part b:"], [50.436, 51.845, "x squared and x."], [51.865, 52.47, "Part c:"], [52.49, 54.972, "a squared b and a b squared."], [57.5, 62.059, "For part a, letters can swap places because of the commutative law."], [62.079, 64.861, "xy equals yx, so yes, they're like terms."], [66.1, 68.539, "For part b, expand the powers."], [68.559, 71.818, "x squared is x times x, but x is just x."], [71.838, 72.309, "So no."], [73.533, 75.652, "For part c, expand again."], [75.672, 81.725, "a squared b is a times a times b, but a b squared is a times b times b."], [81.745, 82.238, "So no."], [83.967, 85.212, "Example three:"], [85.232, 86.93, "collect like terms."], [86.95, 91.45, "Simplify ten x, minus three x, plus three, plus x."], [94.0, 97.511, "Circle the like terms, and remember that x means one x."], [97.531, 100.593, "The x terms are ten x, minus three x and plus x."], [100.613, 102.005, "The constant is three."], [103.233, 105.789, "Group them, taking each sign along:"], [105.809, 108.66, "ten x minus three x plus x, plus three."], [109.9, 112.239, "Now add and subtract the coefficients:"], [112.259, 114.598, "ten minus three plus one equals eight."], [114.618, 116.833, "So the answer is eight x plus three."], [116.853, 119.751, "Eight x and three are unlike terms, so we stop."], [121.5, 122.641, "Example four:"], [122.661, 125.23, "letters in a different order."], [125.25, 130.051, "Simplify four xy, plus two x, minus three yx, minus x."], [132.6, 137.327, "xy and yx are like terms, and two x and x are like terms."], [137.347, 138.243, "Group them:"], [138.263, 141.825, "four xy minus three yx, plus two x minus x."], [143.067, 147.368, "Four minus three equals one, and two minus one equals one."], [147.388, 149.379, "So the answer is xy plus x."], [151.1, 152.261, "Example five:"], [152.281, 153.897, "terms with powers."], [153.917, 159.984, "Simplify three x squared y, plus two xy squared, minus x squared y,"], [160.004, 161.892, "plus four xy squared."], [164.433, 166.762, "Expand to see which are alike."], [166.782, 169.345, "x squared y is x times x times y."], [169.365, 171.85, "xy squared is x times y times y."], [173.1, 176.948, "Group the x squared y terms, and the xy squared terms."], [178.2, 182.553, "Three minus one equals two, and two plus four equals six."], [182.573, 186.696, "So the answer is two x squared y, plus six xy squared."], [188.433, 189.448, "Example six:"], [189.468, 191.344, "check by substitution."], [191.364, 195.74, "Simplify five a, plus two b, plus three a, minus b."], [195.76, 200.05, "Then check using a equals two, and b equals three."], [202.6, 204.026, "Collect like terms."], [204.046, 206.385, "Five a plus three a is eight a."], [206.405, 207.83, "Two b minus b is b."], [207.85, 210.265, "So the answer is eight a plus b."], [211.5, 214.565, "Now substitute into the original expression."], [214.585, 219.614, "Five times two, plus two times three, plus three times two, minus three."], [219.634, 224.102, "That's ten plus six plus six minus three, which equals nineteen."], [225.333, 227.977, "Substitute into the simplified expression."], [227.997, 232.289, "Eight times two plus three is sixteen plus three, which is nineteen."], [232.309, 235.016, "The answers match, so we know it's correct."], [236.767, 239.086, "That's the end of the six worked examples."], [239.106, 241.593, "Now try the questions in your lesson booklet,"], [241.613, 244.212, "and remember to show your working in the boxes."], [244.232, 247.61, "You can check each simplified answer by substituting a value."]], "Lesson2_Theory": [[0.3, 2.261, "Welcome to Headstart algebra."], [2.281, 3.422, "This is Lesson 2:"], [3.442, 5.335, "multiplying algebraic terms."], [5.355, 10.117, "By the end of this video, you'll be able to write terms in index form,"], [10.137, 12.781, "and multiply terms using the index law."], [14.633, 15.954, "First, index form."], [15.974, 21.615, "When the same letter is multiplied by itself, we can write it with an index,"], [21.635, 23.105, "also called a power."], [23.125, 24.52, "a³ means a × a × a."], [25.767, 28.773, "The small raised number, 3, is the index."], [28.793, 32.464, "It tells us how many times the base is multiplied."], [32.484, 34.383, "The base is the letter, a."], [35.633, 38.988, "And a letter with no index has an index of one."], [39.008, 40.639, "So a is the same as a¹."], [42.267, 45.535, "To write in index form, count each letter."], [45.555, 50.781, "In 3 × a × a × a × b, the letter a appears three times, and b once."], [50.801, 52.112, "So we write 3a³b."], [52.132, 56.966, "The number goes first, then the letters in alphabetical order."], [58.2, 59.661, "Try another."], [59.681, 65.587, "2 × x × x × y × y × y has two x's and three y's."], [65.607, 67.438, "So it is 2x²y³."], [69.067, 71.962, "Before you multiply anything, check the sign."], [71.982, 74.553, "A positive times a positive is positive."], [75.8, 78.494, "A negative times a negative is also positive."], [78.514, 80.303, "Two negatives make a positive."], [81.533, 83.694, "A positive times a negative is negative."], [84.933, 88.053, "And a negative times a positive is negative too."], [88.073, 88.273, "So:"], [88.269, 92.436, "same signs give a positive, and different signs give a negative."], [94.067, 96.579, "Now let's multiply terms."], [96.599, 98.91, "We'll use this example:"], [98.93, 100.328, "3a³b × −2a²b²."], [100.348, 102.557, "There are three steps."], [103.8, 104.357, "Step one:"], [104.377, 106.473, "write each term in expanded form."], [106.493, 109.742, "Every letter is written out in full, one at a time."], [110.967, 111.605, "Step two:"], [111.625, 116.285, "group the coefficients together, and group the matching letters."], [116.305, 119.649, "That's 3 and −2, then five a's, and three b's."], [120.9, 122.22, "Step three:"], [122.24, 125.63, "write it back in index form."], [125.65, 131.721, "3 × −2 is −6, five a's is a⁵, and three b's is b³."], [131.741, 134.644, "So the answer is −6a⁵b³."], [136.267, 139.946, "Writing everything out takes a long time, so here is a shortcut."], [139.966, 143.818, "Multiply the coefficients, and add the indices of matching letters."], [145.067, 154.126, "For example, a³ × a⁴ is a × a × a times a × a × a × a, which is seven a's."], [154.146, 155.352, "That's a⁷."], [155.372, 158.788, "We simply added the indices:"], [158.808, 160.015, "3 + 4 = 7."], [161.267, 166.232, "Letters that appear in only one term are just copied across."], [166.252, 167.894, "So 3ab × 2c is 6abc."], [169.533, 171.73, "Be careful about what an index applies to."], [171.75, 175.423, "An index only applies to the number or letter immediately to its left."], [176.667, 180.725, "In 4gh³, the 3 only applies to h."], [180.745, 183.938, "So it's 4 × g × h × h × h."], [185.167, 192.751, "But in (4gh)³, the brackets make the 3 apply to everything inside."], [192.771, 194.825, "So 4 is cubed too:"], [194.845, 197.936, "4³ is 64, so we get 64g³h³."], [199.167, 204.941, "And for a power of a power, multiply the indices."], [204.961, 206.36, "(x²)³ is x⁶."], [208.0, 209.145, "Three helpful hints."], [209.165, 213.224, "First, use brackets when an index should apply to more than one thing."], [214.467, 220.679, "Second, always write the coefficient first, then the letters in alphabetical order."], [220.699, 222.557, "So b × 3 × a becomes 3ab."], [223.8, 226.414, "And third, always check the sign first."], [226.434, 228.441, "Two negatives make a positive."], [230.067, 235.368, "You should now be able to write repeated multiplication in index form,"], [235.388, 237.725, "work out the sign of a product,"], [237.745, 242.438, "multiply terms by multiplying coefficients and adding indices,"], [242.458, 246.087, "and tell the difference between 4gh³ and (4gh)³."], [246.107, 252.017, "Next, watch the worked examples video, then try the questions in your booklet."]], "Lesson2_Worked_Examples": [[0.3, 4.24, "In this video we'll work through seven worked examples from Lesson 2."], [4.26, 7.97, "For each one, pause the video and try the problem yourself first."], [7.99, 11.47, "Then follow the think and write steps to check your thinking."], [13.3, 14.6, "Example one:"], [14.62, 17.679, "writing terms in index form."], [17.699, 22.409, "Simplify 2 × a × a × a, and −9 × b × a × a."], [23.633, 27.887, "For part a, count how many times a appears."], [27.907, 29.079, "Three times."], [29.099, 33.154, "So 2 × a × a × a is 2 × a³, which is 2a³."], [34.4, 38.171, "For part b, the letter a appears twice and b once."], [38.191, 42.949, "Write the number first, then the letters in alphabetical order."], [42.969, 44.162, "So we get −9a²b."], [45.8, 47.113, "Example two:"], [47.133, 49.113, "multiplying terms."], [49.133, 51.112, "Simplify 4ab × 3c."], [52.333, 55.788, "Write each term in expanded form:"], [55.808, 57.684, "4 × a × b × 3 × c."], [58.933, 62.962, "Group the numbers first, then the letters:"], [62.982, 64.697, "4 × 3 × a × b × c."], [65.933, 67.941, "Multiply the numbers."], [67.961, 69.1, "4 × 3 is 12."], [69.12, 71.321, "So the answer is 12abc."], [72.967, 74.587, "Example three:"], [74.607, 77.283, "a negative coefficient."], [77.303, 79.51, "Simplify 5a² × −a⁴."], [80.733, 85.996, "The term −a⁴ has an invisible coefficient of minus one."], [86.016, 88.59, "So we can write it as −1a⁴."], [89.833, 92.895, "Multiply the coefficients:"], [92.915, 94.436, "5 × −1 is −5."], [94.456, 96.925, "Then add the indices:"], [96.945, 98.229, "2 + 4 is 6."], [98.249, 100.48, "The answer is −5a⁶."], [102.133, 103.925, "Example four:"], [103.945, 106.573, "using the shortcut."], [106.593, 109.779, "Simplify −2p²q³ × 7qp⁵."], [111.0, 114.692, "First, multiply the coefficients."], [114.712, 116.266, "−2 × 7 is −14."], [117.5, 119.132, "Now add the indices."], [119.152, 121.775, "For p, that's 2 + 5, which is 7."], [121.795, 127.722, "For q, it's 3 + 1, which is 4, because q on its own has an index of one."], [128.967, 131.201, "Put it together."], [131.221, 134.301, "The answer is −14p⁷q⁴."], [135.933, 137.774, "Example five:"], [137.794, 141.065, "brackets with an index."], [141.085, 143.068, "Expand (3x²)⁴."], [144.3, 150.888, "The 4 applies to everything inside the brackets."], [150.908, 153.779, "So we get 3⁴ × (x²)⁴."], [155.0, 159.817, "3⁴ is 3 × 3 × 3 × 3, which is 81."], [159.837, 165.534, "And for (x²)⁴, we multiply the indices."], [165.554, 167.146, "2 × 4 is 8."], [167.166, 170.371, "So the answer is 81x⁸."], [172.0, 173.228, "Example six:"], [173.248, 175.827, "finding a missing factor."], [175.847, 178.218, "Complete 4a × □ = 8ab²."], [179.467, 182.125, "What do you multiply 4 by to get 8?"], [182.145, 182.967, "4 × 2 is 8."], [184.2, 188.162, "The letter a is already on both sides, so we don't need another one."], [188.182, 190.037, "But b² is missing from the left."], [191.267, 194.314, "So the missing part is 2b²."], [194.334, 196.7, "Check by multiplying:"], [196.72, 198.631, "4a × 2b² is 8ab²."], [198.651, 199.654, "It works."], [201.3, 202.25, "Example seven:"], [202.27, 203.914, "the area of a rectangle."], [203.934, 206.478, "The length is 6x and the width is 8y."], [206.498, 207.448, "Find the area."], [208.7, 211.793, "Area equals length times width."], [211.813, 216.514, "So we multiply 6x × 8y, which is 6 × 8 × x × y."], [216.534, 217.719, "That's 48xy."], [219.367, 221.822, "That's the end of the seven worked examples."], [221.842, 224.353, "Now try the questions in your lesson booklet,"], [224.373, 226.998, "and remember to show your working in the boxes."], [227.018, 228.573, "Always check the sign first!"]], "Lesson3_Theory": [[0.3, 2.101, "Welcome to Headstart algebra."], [2.121, 4.173, "This is Lesson 3, the checkpoint."], [4.193, 7.815, "Today we revise adding, subtracting and multiplying terms,"], [7.835, 11.017, "so you can check you're confident before moving on."], [12.867, 16.53, "First, the parts of an expression."], [16.55, 18.805, "Here's an expression:"], [18.825, 20.863, "4x − 3 + 9y − 4xy²."], [20.883, 26.064, "The terms are separated by plus and minus signs."], [26.084, 30.289, "So the terms are 4x, −3, 9y, and −4xy²."], [31.533, 33.356, "The pronumerals are the letters."], [33.376, 35.428, "In this expression they are x and y."], [36.667, 40.464, "The coefficient is the number multiplying the letters."], [40.484, 42.302, "Here we have 4, 9, and −4."], [42.322, 44.847, "Notice the sign belongs to the term."], [46.067, 49.721, "The constant is the term with no letters, just a number."], [49.741, 50.64, "Here it is −3."], [51.867, 56.169, "And the highest index is the biggest power on a letter."], [56.189, 60.177, "For y, the highest index is 2, from the term −4xy²."], [61.8, 64.958, "Now, a quick revision of Lesson 1."], [64.978, 68.977, "To add and subtract, we collect like terms."], [68.997, 71.5, "Take 5x + 2y − 3x + 4y + 7."], [72.733, 73.61, "Step one:"], [73.63, 75.801, "circle the like terms."], [75.821, 78.489, "The x terms are 5x and −3x."], [78.509, 81.079, "The y terms are 2y and 4y."], [82.3, 82.87, "Step two:"], [82.89, 86.28, "group them together, taking each sign with its term."], [87.5, 88.386, "Step three:"], [88.406, 91.185, "add and subtract the coefficients."], [91.205, 93.408, "5 − 3 is 2, and 2 + 4 is 6."], [93.428, 96.207, "The constant, 7, stays on its own."], [96.227, 98.348, "The answer is 2x + 6y + 7."], [98.368, 103.287, "This works exactly the same way with decimals and fractions."], [104.933, 108.246, "And a quick revision of Lesson 2."], [108.266, 111.983, "To multiply terms, take 3a²b × −4ab³."], [113.233, 113.939, "Step one:"], [113.959, 117.649, "multiply the coefficients, and check the sign."], [117.669, 121.439, "3 × −4 is −12, because the signs are different."], [122.667, 123.434, "Step two:"], [123.454, 126.585, "add the indices of matching letters."], [126.605, 129.385, "For a, that's 2 + 1, which is 3."], [129.405, 132.01, "For b, it's 1 + 3, which is 4."], [133.233, 134.083, "Step three:"], [134.103, 139.932, "write it as the coefficient first, then the letters in alphabetical order."], [139.952, 141.672, "The answer is −12a³b⁴."], [143.3, 147.522, "The most common mistake is mixing up adding and multiplying."], [147.542, 148.512, "3x + 4x is 7x."], [148.532, 150.563, "Only the coefficient changes."], [151.8, 153.598, "But 3x × 4x is 12x²."], [153.618, 158.325, "Here the coefficients multiply, and the indices add."], [159.567, 161.487, "Another way to see it:"], [161.507, 164.044, "x + x is 2x, but x × x is x²."], [164.064, 168.365, "If you're not sure, try a number for x and check."], [170.0, 172.373, "Here are three hints for the checkpoint."], [172.393, 173.928, "First, remember the words:"], [173.948, 178.176, "coefficient is the number multiplying, constant is a number on its own,"], [178.196, 179.911, "and pronumeral is the letter."], [181.133, 185.601, "Second, the highest index is the biggest power on that letter, in any term."], [186.833, 190.766, "And third, look at the sign in front of each term before you add,"], [190.786, 192.043, "subtract or multiply."], [193.667, 194.766, "Now it's your turn."], [194.786, 197.772, "Finish any questions you missed in Lessons 1 and 2,"], [197.792, 202.428, "then do the checkpoint questions, and use the catch-up tracker in your booklet."], [202.448, 205.257, "When you're ready, try the quiz on this website."]], "Lesson3_Worked_Examples": [[0.3, 3.58, "In this video we'll work through five checkpoint examples."], [3.6, 7.279, "For each one, pause the video and try the problem yourself first."], [7.299, 10.75, "Then follow the think and write steps to check your thinking."], [12.6, 13.566, "Example one:"], [13.586, 15.456, "parts of an expression."], [15.476, 19.646, "For 6x² − 5y + 8, name the terms, the coefficients,"], [19.666, 22.521, "the constant and the highest index."], [23.767, 28.166, "The terms are separated by plus and minus signs."], [28.186, 30.928, "They are 6x², −5y, and plus 8."], [32.167, 35.858, "The coefficients are the numbers multiplying the letters:"], [35.878, 36.444, "6 and −5."], [37.667, 40.128, "The constant is the term with no letters."], [40.148, 40.672, "That's 8."], [41.9, 45.705, "And the biggest power of x is 2, so the highest index is 2."], [47.333, 49.19, "Example two:"], [49.21, 50.598, "decimals."], [50.618, 56.697, "Simplify 1.72x + 4.24y − 9.18x − 3.98y."], [57.933, 62.164, "Group the x terms together and the y terms together, keeping each sign."], [63.4, 68.349, "For x, 1.72 − 9.18 is −7.46."], [68.369, 73.141, "For y, 4.24 − 3.98 is 0.26."], [73.161, 78.82, "So the answer is −7.46x + 0.26y."], [80.467, 82.001, "Example three:"], [82.021, 83.778, "add or multiply?"], [83.798, 86.998, "Simplify 2x + 5x and 2x × 5x."], [88.233, 93.178, "For part a, we're adding like terms, so we add the coefficients."], [93.198, 94.032, "2 + 5 is 7."], [94.052, 95.35, "The answer is 7x."], [96.6, 99.431, "For part b, we're multiplying."], [99.451, 106.368, "Multiply the coefficients, 2 × 5 is 10, and add the indices, x × x is x²."], [106.388, 108.173, "The answer is 10x²."], [109.8, 111.648, "Example four:"], [111.668, 114.09, "find the mistake."], [114.11, 118.688, "Sam wrote 7xy² × 8x³y² = 15x⁴y⁴."], [118.708, 120.987, "What went wrong?"], [122.233, 126.605, "Sam added the coefficients, but when we multiply terms,"], [126.625, 128.92, "we multiply the coefficients."], [128.94, 130.517, "7 × 8 is 56, not 15."], [131.767, 134.111, "The indices are right."], [134.131, 136.046, "For x, 1 + 3 is 4."], [136.066, 137.981, "For y, 2 + 2 is 4."], [139.233, 143.824, "So the correct answer is 56x⁴y⁴."], [145.467, 146.986, "Example five:"], [147.006, 149.947, "unlike terms with powers."], [149.967, 153.263, "Simplify 2x + x² − 5x + 3x²."], [154.5, 158.946, "x² and x are unlike terms, so we group the x² terms together,"], [158.966, 160.776, "and the x terms together."], [162.0, 164.803, "1 + 3 is 4, and 2 − 5 is −3."], [164.823, 167.122, "The answer is 4x² − 3x."], [167.142, 171.054, "These two terms are unlike, so we stop."], [172.7, 174.964, "That's the end of the checkpoint examples."], [174.984, 179.477, "Now finish your catch-up tracker, and try the checkpoint questions in your booklet."], [179.497, 182.196, "Show your working, and look for your own mistakes."]], "Lesson4_Theory": [[0.3, 2.245, "Welcome to Headstart algebra."], [2.265, 3.397, "This is Lesson 4:"], [3.417, 5.091, "dividing algebraic terms."], [5.111, 10.715, "By the end of this video, you'll be able to simplify expressions by dividing terms."], [12.567, 15.078, "First, division and fractions."], [15.098, 18.454, "A division can be written as a fraction."], [18.474, 20.817, "So x ÷ 7 is the same as x/7."], [22.067, 25.284, "Anything divided by itself is one."], [25.304, 26.426, "So x/x is 1."], [26.446, 30.234, "In the same way, a/a is 1, and b/b is 1."], [31.467, 34.902, "We'll also use the highest common factor, or H C F."], [34.922, 38.764, "That's the biggest number that divides into both numbers."], [38.784, 40.526, "The H C F of 6 and 3 is 3."], [42.167, 45.746, "Here's how to divide algebraic terms."], [45.766, 48.664, "We'll simplify (6a⁵b³)/(3a³b)."], [48.684, 50.707, "There are four steps."], [51.933, 52.574, "Step one:"], [52.594, 54.997, "write each term in expanded form."], [55.017, 58.814, "On the top, that's 6 times five a's times three b's."], [58.834, 62.485, "On the bottom, it's 3 times three a's times one b."], [63.733, 64.569, "Step two:"], [64.589, 68.277, "divide the coefficients by their H C F."], [68.297, 70.749, "The H C F of 6 and 3 is 3."], [70.769, 74.552, "So 6 ÷ 3 is 2, and the bottom becomes 1."], [75.8, 76.518, "Step three:"], [76.538, 80.474, "cancel the letters that are on both the top and the bottom."], [80.494, 83.223, "Three a's cancel, leaving two a's on top."], [83.243, 85.771, "One b cancels, leaving two b's on top."], [87.0, 87.88, "Step four:"], [87.9, 90.759, "write what's left in index form."], [90.779, 92.559, "The answer is 2a²b²."], [94.2, 95.55, "There's a quicker way:"], [95.57, 96.421, "the index law."], [96.441, 100.78, "Divide the coefficients, and subtract the indices of matching letters,"], [100.8, 101.838, "top minus bottom."], [103.067, 105.791, "For example, (a⁵)/(a³)."], [105.811, 108.298, "The indices subtract:"], [108.318, 109.61, "5 − 3 is 2."], [109.63, 111.997, "So the answer is a²."], [113.233, 118.144, "If the index on the top and the bottom is the same, they cancel completely."], [118.164, 119.13, "(a²)/(a²) is 1."], [120.367, 126.875, "And if the bigger index is on the bottom, the leftover stays on the bottom."], [126.895, 128.616, "(a²)/(a⁵) is 1/(a³)."], [130.267, 133.453, "These divisibility rules help you find the H C F."], [133.473, 136.136, "A number is divisible by 2 if it is even."], [137.367, 141.598, "It's divisible by 3 if its digits add to a multiple of 3."], [141.618, 145.849, "For example, 12 is divisible by 3, because 1 plus 2 is 3."], [147.1, 150.227, "And it's divisible by 5 if it ends in 0 or 5."], [151.867, 155.702, "Sometimes you need to divide by a fraction."], [155.722, 158.482, "Let's simplify (3x)/8 ÷ (5x)/4."], [159.733, 162.224, "To divide, multiply by the reciprocal."], [162.244, 165.395, "That means flip the second fraction upside down,"], [165.415, 167.773, "and change the divide sign to times."], [169.0, 173.045, "Now multiply the tops, and multiply the bottoms."], [173.065, 174.654, "We get (12x)/(40x)."], [175.9, 182.001, "Finally, cancel the x, and divide the top and bottom by their H C F, which is 4."], [182.021, 183.455, "The answer is 3/10."], [185.1, 186.263, "Three helpful hints."], [186.283, 191.056, "First, count carefully when you write a letter with a big index in expanded form."], [192.3, 195.916, "Second, if everything cancels, the answer is 1, not 0."], [195.936, 199.821, "And if the sign is negative, keep it with the coefficient."], [201.067, 204.105, "And third, simplify first, and then substitute."], [204.125, 207.879, "It's much quicker than substituting into the big fraction."], [209.5, 213.128, "You should now be able to write a division as a fraction,"], [213.148, 218.056, "divide the coefficients by their H C F, cancel letters on the top and bottom,"], [218.076, 221.768, "use the index law, and simplify first before substituting."], [221.788, 226.76, "Next, watch the worked examples video, then try the questions in your booklet."]], "Lesson4_Worked_Examples": [[0.3, 4.092, "In this video we'll work through six worked examples from Lesson 4."], [4.112, 7.79, "For each one, pause the video and try the problem yourself first."], [7.81, 11.261, "Then follow the think and write steps to check your thinking."], [13.1, 14.235, "Example one:"], [14.255, 16.544, "cancelling a pronumeral."], [16.564, 18.18, "Simplify (5a²)/a."], [19.4, 22.245, "Write the top in expanded form:"], [22.265, 23.908, "5 × a × a, over a."], [25.133, 29.383, "Cancel one a from the top and the bottom, because a/a is 1."], [29.403, 30.686, "That leaves 5 × a."], [31.933, 33.756, "Write it in index form."], [33.776, 35.118, "The answer is 5a."], [36.767, 38.113, "Example two:"], [38.133, 40.391, "using the index law."], [40.411, 43.124, "Simplify (8a³b)/(2a²b²)."], [44.367, 46.863, "First divide the coefficients."], [46.883, 47.786, "8 ÷ 2 is 4."], [49.033, 52.706, "Now subtract the indices, top minus bottom."], [52.726, 57.43, "For a, that's 3 − 2, which is 1, so one a stays on top."], [57.45, 62.84, "For b, it's 1 − 2, which is −1, so one b is left on the bottom."], [64.067, 65.247, "Put it together."], [65.267, 66.824, "The answer is (4a)/b."], [68.467, 70.034, "Example three:"], [70.054, 74.114, "using the H C F of the coefficients."], [74.134, 76.948, "Simplify (12x⁵y²)/(8x²y)."], [78.2, 81.327, "The H C F of 12 and 8 is 4."], [81.347, 83.308, "Divide both by 4."], [83.328, 86.572, "12 ÷ 4 is 3, and 8 ÷ 4 is 2."], [87.8, 91.82, "For x, 5 − 2 is 3, and it stays on top."], [91.84, 95.86, "For y, 2 − 1 is 1, and it stays on top."], [97.1, 99.965, "So the answer is (3x³y)/2."], [101.6, 103.209, "Example four:"], [103.229, 106.842, "a divide sign, and negatives."], [106.862, 109.85, "Simplify 30a³b² ÷ −6ab²."], [111.1, 112.979, "Divide the coefficients."], [112.999, 117.331, "30 ÷ −6 is −5, because different signs give a negative."], [118.567, 120.419, "For a, 3 − 1 is 2."], [120.439, 125.414, "For b, 2 − 2 is 0, so the b's cancel completely."], [126.667, 128.853, "The answer is −5a²."], [130.5, 132.126, "Example five:"], [132.146, 134.91, "multiply on top first."], [134.93, 137.948, "Simplify (x⁴ × x³)/(x²)."], [139.2, 143.752, "On the top we're multiplying, so add the indices."], [143.772, 144.779, "4 + 3 is 7."], [144.799, 146.738, "That gives (x⁷)/(x²)."], [147.967, 151.765, "Now we divide, so subtract the indices."], [151.785, 152.842, "7 − 2 is 5."], [152.862, 154.506, "The answer is x⁵."], [156.133, 157.339, "Example six:"], [157.359, 159.993, "simplify, then substitute."], [160.013, 165.915, "Simplify (12a³b)/(4a), then evaluate when a = 2 and b = 5."], [167.167, 168.795, "12 ÷ 4 is 3."], [168.815, 171.268, "For a, 3 − 1 is 2."], [171.288, 172.916, "The b stays."], [172.936, 174.976, "So we get 3a²b."], [176.2, 177.581, "Now substitute."], [177.601, 181.037, "3 × 2² × 5 is 3 × 4 × 5, which is 60."], [181.057, 184.866, "Simplifying first made that much quicker."], [186.5, 189.031, "That's the end of the six worked examples."], [189.051, 191.764, "Now try the questions in your lesson booklet,"], [191.784, 194.619, "and remember to show your working in the boxes."], [194.639, 197.413, "If everything cancels, the answer is 1, not 0."]], "Lesson5_Theory": [[0.3, 2.16, "Welcome to Headstart algebra."], [2.18, 3.262, "This is Lesson 5:"], [3.282, 3.91, "expanding."], [3.93, 5.53, "By the end of this video,"], [5.55, 9.484, "you'll be able to expand brackets using the distributive law."], [11.333, 14.31, "Expanding means removing the brackets by multiplying."], [14.33, 17.871, "The term outside the brackets is shared with every term inside."], [17.891, 19.907, "This is called the distributive law."], [21.133, 25.281, "Here's an example with numbers."], [25.301, 32.675, "7(30 + 2) is 7 × 30 + 7 × 2, which is 210 + 14, or 224."], [32.695, 40.204, "In algebra, a(b + c) is a × b + a × c, which is ab + ac."], [41.833, 44.408, "The area model shows why this works."], [44.428, 48.083, "Imagine a rectangle that is 7 tall, and a + 2 wide."], [49.333, 52.459, "We can split it into two smaller rectangles:"], [52.479, 55.534, "one that is 7 by a, and one that is 7 by 2."], [56.767, 62.136, "The areas are 7 × a, which is 7a, and 7 × 2, which is 14."], [63.367, 66.898, "The whole rectangle is 7(a + 2)."], [66.918, 70.117, "The two parts add to 7a + 14."], [71.367, 75.949, "So 7(a + 2) equals 7a + 14."], [77.6, 79.459, "Here's how to expand."], [79.479, 81.427, "Let's try −7p(3q − 4)."], [81.447, 87.511, "The term outside the brackets is negative, which makes signs tricky."], [88.733, 89.43, "Step one:"], [89.45, 94.126, "multiply each term inside the brackets by the term outside."], [94.146, 96.833, "When the outside term is negative,"], [96.853, 100.813, "put each product in brackets to protect the signs."], [100.833, 104.474, "So we get −7p × 3q, plus the bracket −7p × −4."], [105.7, 106.821, "Step two:"], [106.841, 107.961, "simplify."], [107.981, 110.243, "−7p × 3q is −21pq."], [110.263, 118.354, "And −7p × −4 is plus 28p, because two negatives make a positive."], [118.374, 121.65, "The answer is −21pq + 28p."], [123.3, 130.775, "With two brackets, expand each one, then collect like terms."], [130.795, 137.021, "For 5(a + 4) + 2(a + 7), we get 5a + 20 + 2a + 14."], [138.267, 140.867, "Collect the like terms:"], [140.887, 144.626, "5a + 2a is 7a, and 20 + 14 is 34."], [144.646, 147.132, "The answer is 7a + 34."], [148.367, 154.116, "And watch out for a minus sign in front of a bracket."], [154.136, 157.163, "−(a + 2) means −1 × (a + 2)."], [157.183, 160.102, "So every sign inside flips."], [160.122, 162.388, "The answer is −a − 2."], [164.033, 165.317, "Three helpful hints."], [165.337, 168.184, "First, when you multiply by a negative term,"], [168.204, 170.79, "use brackets to keep track of the signs."], [172.033, 176.292, "Second, show all your working, to avoid arithmetic and sign errors."], [177.533, 181.302, "And third, after expanding, always simplify."], [181.322, 183.8, "Simplify, simplify, simplify!"], [185.433, 190.031, "You should now be able to use the distributive law with numbers and letters,"], [190.051, 192.522, "expand when the outside term is negative,"], [192.542, 195.135, "expand two brackets and collect like terms,"], [195.155, 197.687, "and show an expansion using an area model."], [197.707, 202.426, "Next, watch the worked examples video, then try the questions in your booklet."]], "Lesson5_Worked_Examples": [[0.3, 4.264, "In this video we'll work through seven worked examples from Lesson 5."], [4.284, 8.018, "For each one, pause the video and try the problem yourself first."], [8.038, 11.54, "Then follow the think and write steps to check your thinking."], [13.367, 15.132, "Example one:"], [15.152, 19.297, "expanding by a whole number."], [19.317, 28.222, "Expand and simplify 6(a + 4), 2(3x − y), and 3(2x + 4y + 5)."], [29.467, 34.404, "For part a, multiply each term inside by 6."], [34.424, 37.748, "6 × a is 6a, and 6 × 4 is 24."], [37.768, 39.823, "So we get 6a + 24."], [41.067, 46.9, "For part b, the second term is negative, so keep the minus."], [46.92, 49.877, "2 × 3x is 6x, and 2 × y is 2y."], [49.897, 52.059, "The answer is 6x − 2y."], [53.3, 59.614, "For part c, there are three terms inside, so multiply all three by 3."], [59.634, 61.541, "We get 6x + 12y + 15."], [63.167, 65.074, "Example two:"], [65.094, 68.929, "expanding by a variable."], [68.949, 79.369, "Expand and simplify −7p(3q − 4), 2m(5m − 4n), and 5a(a − 3b − 5)."], [80.6, 85.328, "For part a, put the second term in brackets,"], [85.348, 91.804, "and remember that a negative times a negative is a positive."], [91.824, 96.012, "−7p × 3q is −21pq, and −7p × −4 is 28p."], [96.032, 98.387, "So we get −21pq + 28p."], [99.633, 104.32, "For part b, remember that m × m is m²."], [104.34, 109.027, "2m × 5m is 10m², and 2m × −4n is −8mn."], [109.047, 112.123, "The answer is 10m² − 8mn."], [113.367, 119.371, "For part c, multiply all three terms by 5a."], [119.391, 121.333, "5a × a is 5a²."], [121.353, 123.854, "5a × −3b is −15ab."], [123.874, 126.656, "And 5a × −5 is −25a."], [126.676, 131.42, "So the answer is 5a² − 15ab − 25a."], [133.067, 134.372, "Example three:"], [134.392, 135.793, "the area model."], [135.813, 142.326, "Show that 10(a + 3) = 10a + 30 by finding the area of each rectangle."], [143.567, 146.664, "Draw a rectangle 10 wide and a + 3 tall."], [146.684, 151.262, "Split it into a rectangle of height a, and one of height 3."], [151.282, 154.691, "Rectangle one has area 10 × a, which is 10a."], [154.711, 158.042, "Rectangle two has area 10 × 3, which is 30."], [159.267, 163.379, "The large rectangle is the sum of the two."], [163.399, 166.232, "So 10(a + 3) equals 10a + 30."], [167.867, 169.669, "Example four:"], [169.689, 173.455, "two brackets, then collect."], [173.475, 177.521, "Simplify 3(x + 4) + 2(x − 1)."], [178.767, 181.762, "Expand the first bracket."], [181.782, 184.175, "3(x + 4) is 3x + 12."], [185.4, 188.543, "Expand the second bracket."], [188.563, 190.855, "2(x − 1) is 2x − 2."], [192.1, 195.26, "Now add, and collect like terms."], [195.28, 198.441, "3x + 2x is 5x, and 12 − 2 is 10."], [198.461, 200.627, "The answer is 5x + 10."], [202.267, 204.094, "Example five:"], [204.114, 207.221, "subtracting a bracket."], [207.241, 211.201, "Simplify 3(d − 2) − (d + 8)."], [212.433, 218.106, "The expression −(d + 8) means −1 × (d + 8)."], [218.126, 224.196, "So every sign inside flips, and we get −d − 8."], [225.433, 228.616, "Expand the first bracket."], [228.636, 231.051, "3(d − 2) is 3d − 6."], [232.3, 234.845, "Now collect like terms."], [234.865, 238.413, "3d − d is 2d, and −6 − 8 is −14."], [238.433, 240.866, "The answer is 2d − 14."], [242.5, 243.9, "Example six:"], [243.92, 246.504, "expand, then evaluate."], [246.524, 251.829, "Expand 5a(3a + 10), then evaluate when a = 4."], [253.067, 256.108, "Multiply both terms by 5a."], [256.128, 260.347, "5a × 3a is 15a², and 5a × 10 is 50a."], [261.6, 264.41, "Now substitute a = 4."], [264.43, 268.858, "15 × 4² is 15 × 16, which is 240."], [268.878, 271.284, "And 50 × 4 is 200."], [271.304, 273.575, "The total is 440."], [274.8, 277.194, "Check with the original."], [277.214, 282.828, "5 × 4 is 20, and the bracket is 3 × 4 + 10, which is 22."], [282.848, 284.84, "20 × 22 is also 440."], [284.86, 285.947, "It matches."], [287.6, 288.499, "Example seven:"], [288.519, 289.484, "a word problem."], [289.504, 293.094, "In three years Emily will be twice as old as Chantelle."], [293.114, 294.998, "Chantelle is c years old now."], [295.018, 298.346, "Write an expression for Emily's age in three years."], [299.567, 302.633, "In three years, Chantelle will be c + 3."], [303.867, 308.77, "Emily will be twice that, so we write 2(c + 3)."], [310.0, 311.142, "Expand it."], [311.162, 314.396, "2 × c is 2c, and 2 × 3 is 6."], [314.416, 317.301, "So Emily's age is 2c + 6."], [318.933, 321.646, "That's the end of the seven worked examples."], [321.666, 324.441, "Now try the questions in your lesson booklet,"], [324.461, 327.36, "and remember to show your working in the boxes."], [327.38, 329.161, "Simplify, simplify, simplify!"]], "Lesson6_Theory": [[0.3, 2.274, "Welcome to Headstart algebra."], [2.294, 3.444, "This is Lesson 6:"], [3.464, 4.269, "factorising."], [4.289, 9.633, "By the end of this video, you'll be able to find the H C F of algebraic terms,"], [9.653, 13.072, "and factorise expressions by taking out the H C F."], [14.9, 15.892, "First, factors."], [15.912, 18.388, "A factor divides exactly into a term."], [18.408, 22.233, "A common factor divides exactly into every term in a set."], [23.467, 28.51, "The highest common factor, or H C F, is the product of all the common factors."], [28.53, 31.691, "It can have a number part, and a pronumeral part."], [33.333, 35.211, "Here are some examples."], [35.231, 37.439, "The H C F of x and 7x is x."], [38.667, 41.945, "The H C F of 6m, 12mn and 8mp is 2m."], [41.965, 48.084, "The number 2 divides into 6, 12 and 8, and m is in all three terms."], [49.333, 53.662, "And the H C F of 15a³bc and 9a²c is 3a²c."], [53.682, 56.526, "Let's see how to find that."], [58.167, 62.039, "To find the H C F, follow three steps."], [62.059, 64.703, "We'll use 15a³bc and 9a²c."], [65.933, 66.944, "Step one:"], [66.964, 73.815, "write each term as a product of prime and algebraic factors."], [73.835, 77.937, "15a³bc is 3 × 5 × a × a × a × b × c."], [77.957, 81.372, "And 9a²c is 3 × 3 × a × a × c."], [82.6, 83.305, "Step two:"], [83.325, 85.4, "circle the common factors."], [85.42, 88.461, "Both terms have a 3, two a's, and a c."], [89.7, 90.932, "Step three:"], [90.952, 92.526, "multiply them."], [92.546, 95.03, "3 × a × a × c is 3a²c."], [95.05, 96.966, "That's the H C F."], [98.6, 102.407, "Factorising is the opposite of expanding."], [102.427, 106.047, "When we expand, we remove the brackets:"], [106.067, 108.38, "7(a + 2) becomes 7a + 14."], [109.6, 114.307, "When we factorise, we put the brackets back:"], [114.327, 116.993, "7a + 14 becomes 7(a + 2)."], [118.633, 120.932, "Now let's factorise 8x + 28."], [120.952, 122.672, "There are four steps."], [123.9, 124.643, "Step one:"], [124.663, 127.693, "identify the H C F of all the terms."], [127.713, 129.981, "The H C F of 8 and 28 is 4."], [131.233, 131.85, "Step two:"], [131.87, 134.54, "write the H C F in front of a bracket."], [135.767, 136.911, "Step three:"], [136.931, 142.202, "inside the bracket, divide each term by the H C F."], [142.222, 145.377, "8x ÷ 4 is 2x, and 28 ÷ 4 is 7."], [146.6, 147.532, "Step four:"], [147.552, 149.532, "simplify the bracket."], [149.552, 151.818, "The answer is 4(2x + 7)."], [151.838, 155.437, "And you can always check by expanding."], [155.457, 158.295, "4 × 2x is 8x, and 4 × 7 is 28."], [158.315, 161.342, "We get back to where we started."], [162.967, 168.364, "Sometimes it's best to take out a negative H C F,"], [168.384, 173.118, "especially when the first term is negative."], [173.138, 176.324, "For −4a − 12, we take out −4."], [176.344, 180.525, "−4a ÷ −4 is a, and −12 ÷ −4 is plus 3."], [180.545, 182.736, "So we get −4(a + 3)."], [183.967, 186.386, "Check by expanding:"], [186.406, 190.624, "−4 × a is −4a, and −4 × 3 is −12."], [190.644, 192.036, "It matches."], [193.667, 194.837, "Three helpful hints."], [194.857, 199.599, "First, look at the coefficients and all the letters when you look for the H C F."], [200.833, 205.096, "Second, take out the highest common factor."], [205.116, 210.873, "If you only take out part of it, you must factorise again."], [210.893, 216.052, "4a + 8 = 2(2a + 4) is not finished, but 4(a + 2) is."], [217.3, 217.849, "And third,"], [217.869, 222.8, "the number of terms inside the bracket must match the number of terms you started with."], [224.433, 228.86, "You should now be able to write a term as a product of its factors,"], [228.88, 232.775, "find the H C F of terms, factorise by taking out the H C F,"], [232.795, 237.62, "factorise with indices and with a negative H C F, and check by expanding."], [237.64, 242.796, "Next, watch the worked examples video, then try the questions in your booklet."]], "Lesson6_Worked_Examples": [[0.3, 4.194, "In this video we'll work through five worked examples from Lesson 6."], [4.214, 7.936, "For each one, pause the video and try the problem yourself first."], [7.956, 11.447, "Then follow the think and write steps to check your thinking."], [13.3, 14.506, "Example one:"], [14.526, 16.755, "identifying the H C F."], [16.775, 21.967, "Find the H C F of 2a and 5a, and of 12xy and −18x³."], [23.2, 28.889, "For part a, write each term as a product of prime and algebraic factors."], [28.909, 31.188, "2a is 2 × a, and 5a is 5 × a."], [32.433, 34.534, "The only common factor is a."], [34.554, 35.897, "So the H C F is a."], [37.133, 41.07, "For part b, write each as a product."], [41.09, 46.016, "A negative can be written as times minus one."], [46.036, 48.873, "12xy is 2 × 2 × 3 × x × y."], [48.893, 53.269, "And −18x³ is −1 × 2 × 3 × 3 × x × x × x."], [54.5, 57.248, "Multiply the common factors:"], [57.268, 58.434, "2, 3, and x."], [58.454, 60.016, "The H C F is 6x."], [61.667, 63.182, "Example two:"], [63.202, 64.718, "factorising."], [64.738, 69.196, "Factorise 8x + 28 and 9xyz − 12wxy."], [70.433, 75.536, "For part a, the H C F of 8 and 28 is 4."], [75.556, 78.425, "Divide each term by 4."], [78.445, 82.366, "8x ÷ 4 is 2x, and 28 ÷ 4 is 7."], [82.386, 84.992, "So we get 4(2x + 7)."], [86.233, 90.798, "For part b, the H C F of 9xyz and 12wxy is 3xy."], [90.818, 93.627, "Write that outside a bracket."], [94.867, 98.384, "Divide each term by 3xy."], [98.404, 104.281, "9xyz ÷ 3xy is 3z, and 12wxy ÷ 3xy is 4w."], [104.301, 107.376, "The minus sign stays."], [107.396, 111.799, "So the answer is 3xy(3z − 4w)."], [113.433, 115.086, "Example three:"], [115.106, 117.356, "terms with indices."], [117.376, 121.776, "Factorise a² − 6a and 10m³n + 15m²n²."], [123.0, 128.045, "For part a, a² is a × a, so the H C F is a."], [128.065, 130.636, "Divide each term by a."], [130.656, 132.52, "We get a(a − 6)."], [133.767, 137.337, "For part b, the H C F of 10 and 15 is 5."], [137.357, 142.723, "The lowest power of m is m², and the lowest power of n is n."], [142.743, 144.608, "So the H C F is 5m²n."], [145.833, 149.587, "Divide each term by 5m²n."], [149.607, 156.229, "10m³n ÷ 5m²n is 2m, and 15m²n² ÷ 5m²n is 3n."], [157.467, 161.894, "The answer is 5m²n(2m + 3n)."], [163.533, 164.866, "Example four:"], [164.886, 166.636, "a negative H C F."], [166.656, 168.613, "Factorise −4a − 12."], [169.833, 173.255, "Take out −4, the H C F with a negative sign."], [174.5, 177.922, "Divide each term by −4."], [177.942, 183.609, "−4a ÷ −4 is a, and −12 ÷ −4 is plus 3."], [183.629, 186.602, "So we get −4(a + 3)."], [187.833, 189.952, "Check by expanding."], [189.972, 193.666, "−4 × a is −4a, and −4 × 3 is −12."], [193.686, 196.368, "It matches the original."], [198.0, 199.019, "Example five:"], [199.039, 200.457, "a composite shape."], [200.477, 203.253, "A rectangle is 5x wide and 3y high."], [203.273, 207.328, "A triangle sits on top, with base 5x and height 2x."], [207.348, 209.965, "Find the area, then factorise it."], [211.2, 215.023, "The rectangle's area is length times width."], [215.043, 216.453, "5x × 3y is 15xy."], [217.7, 222.938, "The triangle's area is half times base times height."], [222.958, 224.86, "½ × 5x × 2x is 5x²."], [226.1, 230.141, "The total area is 15xy + 5x²."], [230.161, 232.381, "The H C F is 5x."], [232.401, 237.002, "So we factorise it as 5x(3y + x)."], [238.633, 241.007, "That's the end of the five worked examples."], [241.027, 243.512, "Now try the questions in your lesson booklet,"], [243.532, 246.295, "and remember to check each answer by expanding it."]], "Lesson7_Theory": [[0.3, 2.194, "Welcome to Headstart algebra."], [2.214, 4.108, "This is Lesson 7, the review."], [4.128, 7.211, "We'll bring together everything you've learned:"], [7.231, 11.237, "collecting, multiplying, dividing, expanding and factorising."], [13.067, 15.011, "Here's a summary of the five skills."], [15.031, 16.975, "Let's go through them one at a time."], [18.2, 22.142, "To collect like terms, look for the same letters with the same powers,"], [22.162, 24.237, "and add or subtract the coefficients."], [25.467, 29.989, "To multiply, multiply the coefficients and add the indices of matching letters."], [31.233, 36.63, "To divide, divide the coefficients by their H C F, and subtract the indices."], [36.65, 37.485, "Then cancel."], [38.733, 43.344, "To expand, multiply every term inside the bracket by the term outside."], [44.567, 49.278, "And to factorise, take out the H C F, and divide every term by it."], [50.9, 54.604, "Now, some common mistakes to watch for."], [54.624, 58.71, "First, don't mix up adding and multiplying."], [58.73, 62.052, "3x + 4x is 7x, but 3x × 4x is 12x²."], [63.3, 66.187, "Second, unlike terms can't be combined."], [66.207, 68.348, "2x + 3y cannot be simplified."], [69.6, 76.353, "Third, a minus sign in front of a bracket flips every sign inside."], [76.373, 78.303, "−(a + 2) is −a − 2."], [79.533, 83.98, "And fourth, when you factorise, take out the highest common factor,"], [84.0, 85.847, "and divide every term by it."], [85.867, 88.714, "A term that is all H C F leaves a 1 behind."], [90.367, 92.309, "How do you choose the right skill?"], [92.329, 93.637, "Look at the expression."], [93.657, 98.313, "If the same letters and powers are being added or subtracted, collect like terms."], [99.533, 102.26, "If terms are being multiplied, add the indices."], [103.5, 106.412, "If terms are being divided, subtract the indices."], [107.633, 110.441, "If there's a bracket with a term outside, expand."], [111.667, 114.83, "And if you have a sum with a common factor, factorise."], [116.467, 124.321, "Expanding and factorising are opposites, so you can use one to check the other."], [124.341, 128.407, "Here, −7p(3q − 4) expands to −21pq + 28p."], [129.633, 137.699, "And 15a³bc + 9a²c factorises to 3a²c(5ab + 3)."], [138.933, 141.995, "To check a factorised answer, expand it."], [142.015, 147.002, "3a²c(5ab + 3) takes you straight back to the original expression."], [147.022, 151.238, "You can also check any answer by substituting a number."], [152.867, 154.006, "Now it's your turn."], [154.026, 156.69, "Finish the catch-up tracker in your booklet,"], [156.71, 159.801, "for any questions you missed in Lessons 4, 5 and 6."], [159.821, 163.644, "Then do the review questions, and try the quiz on this website."]], "Lesson7_Worked_Examples": [[0.3, 3.313, "In this video we'll work through five review examples."], [3.333, 8.032, "For each one, decide which skill you need, then pause the video and try it yourself."], [8.052, 11.459, "Then follow the think and write steps to check your thinking."], [13.3, 14.95, "Example one:"], [14.97, 16.619, "which skill?"], [16.639, 19.402, "Look at −7p(3q − 4)."], [20.633, 24.88, "There's a bracket with a term outside, so we need to expand."], [24.9, 27.226, "Multiply each term inside by −7p."], [28.467, 30.791, "−7p × 3q is −21pq."], [30.811, 38.475, "And −7p × −4 is 28p, because two negatives make a positive."], [38.495, 41.861, "The answer is −21pq + 28p."], [43.5, 44.932, "Example two:"], [44.952, 46.383, "which skill?"], [46.403, 49.044, "Look at 15a³bc + 9a²c."], [50.267, 53.982, "This is a sum with a common factor, so we factorise."], [54.002, 57.933, "The H C F is 3a²c, so write that in front of a bracket."], [59.167, 63.211, "Divide each term by 3a²c."], [63.231, 70.201, "15a³bc ÷ 3a²c is 5ab, and 9a²c ÷ 3a²c is 3."], [71.433, 75.548, "So the answer is 3a²c(5ab + 3)."], [75.568, 78.216, "To check, expand it."], [78.236, 83.951, "3a²c × 5ab is 15a³bc, and 3a²c × 3 is 9a²c."], [83.971, 87.553, "We're back to the original."], [89.2, 90.703, "Example three:"], [90.723, 93.424, "spot and fix the mistake."], [93.444, 96.579, "Alex wrote −(a + 2) = −a + 2."], [96.599, 98.32, "What went wrong?"], [99.567, 105.53, "The expression −(a + 2) means −1 × (a + 2)."], [105.55, 109.983, "So we multiply both terms by −1."], [111.233, 114.12, "−1 × a is −a, and −1 × 2 is −2."], [114.14, 120.683, "The minus flips every sign inside the bracket, not just the first one."], [120.703, 123.402, "The correct answer is −a − 2."], [125.033, 126.976, "Example four:"], [126.996, 130.147, "expand, then collect."], [130.167, 134.374, "Simplify 4(x + 2) − (x − 3)."], [135.6, 138.552, "Expand the first bracket."], [138.572, 140.811, "4(x + 2) is 4x + 8."], [142.033, 144.601, "Now the second bracket."], [144.621, 150.0, "−(x − 3) flips every sign, so it becomes −x + 3."], [151.233, 153.144, "Collect like terms."], [153.164, 156.192, "4x − x is 3x, and 8 + 3 is 11."], [156.212, 158.427, "The answer is 3x + 11."], [160.067, 161.064, "Example five:"], [161.084, 162.708, "a real-world problem."], [162.728, 168.422, "A rectangle has width x centimetres, and area x² + 6x square centimetres."], [168.442, 169.675, "Find its length."], [170.9, 177.807, "Area is length times width, so the length is the area divided by the width."], [177.827, 181.594, "We can find this by factorising the area."], [181.614, 184.18, "The H C F of x² and 6x is x."], [184.2, 186.304, "So x² + 6x is x(x + 6)."], [187.533, 190.644, "The width is x, so the other factor is the length."], [190.664, 192.648, "The length is x + 6 centimetres."], [194.3, 196.352, "That's the end of the review examples."], [196.372, 200.659, "Now finish your catch-up tracker, and try the review questions in your booklet."], [200.679, 204.203, "Remember to choose the right skill first, and check your answers."]]};
